fn main() {
    let original = std::fs::read_to_string("hello.yaml").unwrap();
    let doc = cnc_formats::miniyaml::MiniYamlDoc::parse_str(&original).unwrap();
    let [greeting] = doc.nodes() else { panic!("expected one root"); };
    let [text] = greeting.children() else { panic!("expected one child"); };
    assert_eq!(greeting.key(), "Greeting");
    assert_eq!(text.key(), "Text");
    assert!(text.children().is_empty());
    println!("{}", text.value().unwrap());
}
